def grid_pattern(H: int, W: int, N: int) -> None:
    grid = []
    for _ in range(H):
        grid.append(["."] * W)

    i = 0
    j = 0
    p = 0
    directions = [(-1, 0), (0, 1), (1, 0), (0, -1)]

    for _ in range(N):
        if grid[i][j] == ".":
            grid[i][j] = "#"
            p = (p + 1) % 4
        elif grid[i][j] == "#":
            grid[i][j] = "."
            p = (p - 1 + 4) % 4

        i = (i + directions[p][0] + H) % H
        j = (j + directions[p][1] + W) % W

    for row in grid:
        print("".join(row))
